const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,bench,actions,tab=location.hash.slice(1)||'overview',scenario='100m_peak',region='SG',volume=3,history=90,copies=.8,phase='All',completed={};try{completed=JSON.parse(localStorage.getItem('sovereign-pilot-progress')||'{}');}catch{}
const fmt=(n,d=0)=>Number(n).toLocaleString('en-GB',{maximumFractionDigits:d}),ms=n=>n>=1000?fmt(n/1000,2)+' s':fmt(n,1)+' ms',chips=(v,c='')=>`<span class="chip ${c}">${esc(v)}</span>`,opName={party_read:'Party lookup',relationship_read:'Relationship view',write:'Local commit'};
const card=(title,body)=>`<section class="scale-card"><h2>${title}</h2>${body}</section>`;
const table=(head,rows)=>`<div class="tablewrap"><table class="scale-matrix"><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function chart(metrics){const max=Math.max(...metrics.map(x=>x.p99_ms),250),w=640,left=140;return `<div class="scale-chart"><svg viewBox="0 0 640 228" role="img" aria-label="Simulated p95 and p99 latency for the selected region and workload"><title>Simulated latency in milliseconds</title>${metrics.map((m,i)=>{const y=35+i*61;return `<text x="0" y="${y+17}" font-size="12" fill="#476044">${opName[m.operation]}</text><rect x="${left}" y="${y}" height="12" width="${m.p95_ms/max*360}" rx="3" fill="#88a67b"/><rect x="${left}" y="${y+17}" height="12" width="${m.p99_ms/max*360}" rx="3" fill="#2f6546"/><text x="${left+m.p99_ms/max*360+8}" y="${y+28}" font-size="11" fill="#375735">${ms(m.p99_ms)}</text>`;}).join('')}<text x="140" y="222" font-size="10" fill="#6a7e61">Linear width · per-operation quantiles · p99 value labelled</text></svg></div><div class="scale-key"><span><i style="background:#88a67b"></i>p95 simulated</span><span><i style="background:#2f6546"></i>p99 simulated</span></div>`;}
function targets(){return table(['Operation','p95 target','p99 target','Boundary'],data.assumptions.targets.map(t=>[t.name,ms(t.p95_ms),ms(t.p99_ms),esc(t.boundary)]));}
function overview(){const storage=data.storage.at(-1);return `<div class="scale-hero"><div><div class="eyebrow">CAPACITY IS A WORKLOAD QUESTION</div><h2>Keep the local transaction small.<br>Give the tails room to breathe.</h2><p>The improved architecture is plausible at this scale. The current PoC’s full scans and global lock are not. These scenarios expose the capacity, sharing and retention assumptions a pilot needs to prove.</p></div><div class="hero-numbers"><div><b>50m</b><span>PARTIES</span></div><div><b>100m</b><span>RELATIONSHIPS</span></div></div></div><div class="metrics">${[['Simulated requests',fmt(data.method.foreground_events/1e6,2)+'m','16 scenarios × 3 deterministic seeds'],['Design peak','35,000 /s','30k reads + 5k business writes'],['Business rows',fmt(storage.source_rows/1e9,2)+'bn','Including holdings, identifiers and history'],['Provisioned DB',fmt(storage.provisioned_tb,1)+' TB','Central model · 60% disk fill · all regions']].map(([a,b,c])=>`<div class="metric"><div class="metric-label">${a}</div><div class="metric-value">${b}</div><small>${c}</small></div>`).join('')}</div><div class="scale-two">${card('The targets I would take into pilot','<p>Measure these at regional gateway ingress, for bounded operations, at the agreed workload. They are acceptance goals, not achieved database measurements. Keep WAN-routed operations on a separate budget.</p><div class="scale-numberline"><div><b>75 ms</b><small>party lookup p99</small></div><div><b>150 ms</b><small>relationship view p99</small></div><div><b>250 ms</b><small>local commit p99</small></div></div>')}${card('The three findings that change the design','<ul><li>A 25% peak traffic increase overloads the assumed capacity. Aim for ≤60% of measured limiting capacity at design peak.</li><li>High-degree parties create hundreds of scope updates. Use resource epochs and queued materialisation.</li><li>History and audit dominate growth. Hot retention and regional archives are architectural decisions.</li></ul>')}</div><section class="panel"><div class="panelhead"><h2>Proposed performance contract</h2>${chips('ENGINEERING TARGETS')}</div>${targets()}</section><div class="scale-card" style="margin-top:22px"><img class="scale-image" src="scale/capacity-results.png" alt="Four simulation charts: overload latency, logical storage, outage recovery and graph versus delta bandwidth."><div class="scale-actionbar"><a href="scale/capacity-results.svg" download>Download chart SVG ↗</a><a href="scale/scale-and-pilot.md" download>Full assessment ↗</a></div></div>`;}
function workload(){const s=data.scenarios.find(x=>x.id===scenario),metrics=s.metrics.filter(m=>m.region===region);return `<div class="scale-controls"><label>Executed scenario<select id="scenario">${data.scenarios.map(x=>`<option value="${x.id}" ${scenario===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Regional result<select id="region">${['SG','UK','US'].map(r=>`<option ${r===region?'selected':''}>${r}</option>`).join('')}</select></label></div><div class="capacity-stamp ${s.stable?'':'danger'}"><b>${s.stable?'Stable under assumed capacity':'Overload — no sustainable steady-state p99'}</b> · ${fmt(s.rps)} offered API requests/s globally · ${fmt(s.duration_seconds,1)} seconds per run · busiest DB demand ${fmt(s.max_db_demand_ratio*100,1)}%${s.hot_key_demand_ratio>1?' · hot-key demand '+fmt(s.hot_key_demand_ratio,2)+'× capacity':''}. A finite workload snapshot is not a 60-minute benchmark.</div><div class="scale-two">${card('Latency distribution · '+region,chart(metrics))}${card('Targets versus the selected run',table(['Operation','p95','p99','p99 goal','>1s'],metrics.map(m=>[opName[m.operation],ms(m.p95_ms),ms(m.p99_ms),ms(data.assumptions.targets.find(t=>t.id===m.operation).p99_ms),fmt(m.over_1s_pct,2)+'%']))+'<p>Timeouts are counted as over-one-second responses. The simulator retains them in its queue; a real admission/deadline system should shed overload. No successful-only percentile filter is applied.</p>')}</div><section class="panel"><div class="panelhead"><h2>Tail detail and sampling variation</h2></div>${table(['Operation','p99.9','DB wait p99','p99 range across seeds','Observed sample events'],metrics.map(m=>[opName[m.operation],ms(m.p999_ms),ms(m.db_wait_p99_ms),ms(m.p99_min_ms)+' – '+ms(m.p99_max_ms),fmt(m.samples)]))}</section><div class="scale-two">${card('A 30-minute recipient outage',table(['Recovery service / incoming','Backlog','Drain time'],data.recovery.map(r=>[r.service_factor+'×',fmt(r.initial_jobs/1e6,2)+'m jobs',fmt(r.drain_minutes)+' minutes']))+'<p>New traffic continues during recovery. Revocation messages need a priority lane; live purge cannot have a finite completion bound while its destination is unavailable.</p>')}${card('Observed local OPA timings',table(['Resource rows','HTTP p95','HTTP p99'],bench.results.map(r=>[r.rows,ms(r.p95_ms),ms(r.p99_ms)]))+'<p>Actual OPA 1.9.0 · 1,200 warmed sequential loopback requests per size. Shared 8-vCPU quota / 8 GiB sandbox; telemetry disabled. No DB, WAN, TLS or concurrent production traffic.</p>')}</div><details class="scale-method"><summary>Read the simulation limits and assumptions</summary><ul>${data.method.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><p>Service medians: DB 3/10/14 ms for party/relationship/write; local OPA 1.1 ms on small facts; local network 2.5 ms. DB concurrency slots 192/192/96 are abstract calibration inputs, not node or CPU counts. All inputs are downloadable.</p></details>`;}
function storagePage(){const v=data.storage[volume],s=data.storage_sensitivity.find(x=>x.history_days===history&&x.copies===copies);return `<div class="scale-controls"><label>Population scale<select id="volume">${data.storage.map((x,i)=>`<option value="${i}" ${i===volume?'selected':''}>${fmt(x.relationships/1e6)}m relationships / ${fmt(x.parties/1e6,1)}m parties</option>`).join('')}</select></label></div><div class="scale-two">${card('Rows become a multi-billion-row estate',table(['Business dataset','Rows','Assumed row bytes'],v.tables.map(t=>[t.table,fmt(t.rows),t.row_bytes])))}${card('Physical storage bridge',table(['Stage','Amount'],[['Logical data incl. hot audit',fmt(v.logical_tb,2)+' TB'],['Indexes / KV / MVCC', '1.7× / 1.35× / 1.25×'],['Regional replication','RF=3'],['Replicated bytes used',fmt(v.replicated_used_tb,1)+' TB'],['Provisioned at 60% fill',fmt(v.provisioned_tb,1)+' TB'],['Audit archive per year',fmt(v.audit_annual_archive_tb,1)+' TB raw']])+'<p>Decimal TB. No compression saving assumed. Backup retention, broker disks, archive redundancy and extra sovereign country stores are additional. Actual bytes per row and churn must replace these inputs.</p>')}</div><section class="scale-card"><div class="eyebrow">FULL 100M RELATIONSHIP SENSITIVITY</div><h2>Retention and sharing change the footprint.</h2><div class="scale-controls"><label>Contact history retention<select id="history">${[30,90,365].map(h=>`<option value="${h}" ${h===history?'selected':''}>${h} days</option>`).join('')}</select></label><label>Average remote relationship copies<select id="copies">${[.3,.8,1.5].map(c=>`<option value="${c}" ${c===copies?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="scale-numberline"><div><b>${fmt(s.logical_tb,2)} TB</b><small>logical incl. 7-day audit</small></div><div><b>${fmt(s.replicated_used_tb,1)} TB</b><small>replicated used</small></div><div><b>${fmt(s.provisioned_tb,1)} TB</b><small>provisioned at 60%</small></div></div></section><div class="scale-two">${card('Shared-party amplification',table(['Party population','Relationships participated in','Share of edges'],data.fanout.distribution.map(x=>[fmt(x.parties),x.degree,fmt(x.edge_share*100,1)+'%']))+'<p>20% degree-weighted change traffic raises mean fanout from 2.5 to 33.9; p99 party updates touch 610 scopes. This is a synthetic skew scenario, not a measured bank distribution.</p>')}${card('Change the work, not just the hardware',table(['Propagation plan','Destination jobs/s','Payload MB/s'],[['Repeated full graph',fmt(data.fanout.baseline_jobs_per_second),fmt(data.fanout.full_snapshot_mb_s,1)],['Deduplicated resource deltas',fmt(data.fanout.optimized_jobs_per_second),fmt(data.fanout.optimized_delta_mb_s,1)]])+'<p>The saving requires a new shared-resource projection/import contract. Ordinary deltas alone still repeat work per relationship. Preserve entity/purpose controls even when payloads are physically deduplicated.</p>')}</div>`;}
function pilot(){const rows=actions.filter(x=>phase==='All'||x.phase===phase),count=actions.filter(a=>completed[a.id]).length;return `<div class="pilot-stage"><h2>From a convincing PoC to a controlled bank pilot.</h2><p>24 actions, explicit owners, dependencies and exit evidence. Indicative 12–14 weeks with an experienced cross-functional team and timely approvals. Start with approved 100k parties / 200k relationships; rehearse full 50m / 100m volume separately with synthetic data.</p></div><div class="scale-controls"><label>Delivery phase<select id="phase">${['All',...new Set(actions.map(a=>a.phase))].map(p=>`<option ${phase===p?'selected':''}>${p}</option>`).join('')}</select></label><div><b>${count} / ${actions.length}</b><p class="scale-footnote">Personal checklist only. Ticks are stored in this browser and do not certify completion.</p></div><a class="link" href="scale/pilot-actions.csv" download>Download action CSV ↗</a></div><div class="scale-card">${rows.map(a=>`<article class="pilot-action ${completed[a.id]?'done':''}"><input type="checkbox" id="check-${a.id}" data-check="${a.id}" aria-label="Mark ${a.id} complete in personal checklist" ${completed[a.id]?'checked':''}><div><div class="pilot-meta">${a.id} / ${a.priority} / ${esc(a.phase.toUpperCase())} / WEEKS ${a.weeks}</div><h3><label for="check-${a.id}">${esc(a.action)}</label></h3><p>${esc(a.owner)} · Depends on ${esc(a.dependency)}</p><details><summary>Exit evidence</summary><p>${esc(a.exit)}</p></details></div></article>`).join('')}</div>`;}
function render(){if(!['overview','workloads','storage','pilot'].includes(tab))tab='overview';$('#main').innerHTML=`<div class="titlebar"><div><div class="eyebrow">SCALE ASSESSMENT / 11 OCTOBER 2026</div><h1>Capacity & pilot</h1><p class="subtitle">An explicit model of the work, the tails and the path to operational readiness.</p></div><a class="link" href="/design/performance-scale.html">Architecture decisions ↗</a></div><nav class="scale-tabs" aria-label="Capacity sections">${[['overview','Executive view'],['workloads','Workloads & tails'],['storage','Storage & fanout'],['pilot','Pilot action plan']].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}">${label}</button>`).join('')}</nav>${tab==='overview'?overview():tab==='workloads'?workload():tab==='storage'?storagePage():pilot()}<div class="scale-actionbar"><a href="isolation.html">Work isolation model</a><a href="scale/assumptions.json" download>Assumptions JSON</a><a href="scale/latency.csv" download>Latency CSV</a><a href="scale/simulation.json" download>Full simulation results</a><a href="scale/scale-and-pilot.md" download>Assessment & backlog</a><a href="https://github.com/paulcull/sovereign-federation-lab">Source + reproducer</a></div>`;$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;location.hash=tab;render();});for(const [id,set]of Object.entries({scenario:v=>scenario=v,region:v=>region=v,volume:v=>volume=+v,history:v=>history=+v,copies:v=>copies=+v,phase:v=>phase=v})){if($('#'+id))$('#'+id).onchange=e=>{set(e.target.value);render();};}$$('[data-check]').forEach(el=>el.onchange=()=>{completed[el.dataset.check]=el.checked;try{localStorage.setItem('sovereign-pilot-progress',JSON.stringify(completed));}catch{}render();});}
window.addEventListener('hashchange',()=>{tab=location.hash.slice(1);render();});try{[data,bench,actions]=await Promise.all(['simulation.json','opa_microbench.json','pilot_actions.json'].map(f=>fetch('scale/'+f).then(r=>{if(!r.ok)throw Error('Unable to load model file');return r.json();})));render();}catch(e){$('#main').textContent=e.message;}
